mapper.select:
SELECT
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DOC_STATUS IN ('REQUEST', 'PROGRESS')
           AND (
                M.CURR_APPROVER_ID = #{userId}
                OR EXISTS (
                    SELECT 1
                      FROM TB_AM03M02 G
                     WHERE G.ORIGIN_USER_ID = M.CURR_APPROVER_ID
                       AND G.DELEGATE_USER_ID = #{userId}
                       AND G.USE_YN = 'Y'
                       AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN G.START_DT AND G.END_DT
                )
           )
    ) AS INBOX_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DOC_STATUS IN ('REQUEST', 'PROGRESS')
           AND (
                M.DRA_USER_ID = #{userId}
                OR EXISTS (
                    SELECT 1 FROM TB_AM11D01 D
                     WHERE D.DOC_ID = M.DOC_ID AND D.APPROVER_ID = #{userId}
                )
           )
    ) AS PROGRESS_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DRA_USER_ID = #{userId}
           AND M.DOC_STATUS != 'DRAFT'
    ) AS DRAFTED_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DOC_STATUS = 'COMPLETED'
           AND (
                M.DRA_USER_ID = #{userId}
                OR EXISTS (
                    SELECT 1 FROM TB_AM11D01 D
                     WHERE D.DOC_ID = M.DOC_ID AND D.APPROVER_ID = #{userId}
                )
           )
    ) AS COMPLETED_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DOC_STATUS = 'REJECTED'
           AND (
                M.DRA_USER_ID = #{userId}
                OR EXISTS (
                    SELECT 1 FROM TB_AM11D01 D
                     WHERE D.DOC_ID = M.DOC_ID AND D.APPROVER_ID = #{userId}
                )
           )
    ) AS REJECTED_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE EXISTS (
                SELECT 1 FROM TB_AM11D01 D
                 WHERE D.DOC_ID = M.DOC_ID
                   AND D.APPROVER_ID = #{userId}
                   AND D.LINE_TYPE = 'REF'
         )
    ) AS REFERENCED_CNT,
    (
        SELECT COUNT(*)
          FROM TB_AM11M01 M
         WHERE M.DRA_USER_ID = #{userId}
           AND M.DOC_STATUS = 'DRAFT'
    ) AS TEMP_CNT
  FROM DUAL
